import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import Login from "./components/Login";
import Register from "./components/Register";
import Dashboard from "./components/Dashboard";
import DashboardVendedor from "./components/DashboardVendedor";
import Catalogo from "./components/Catalogo";
import ProductoDetalle from "./components/ProductoDetalle";
import Favoritos from "./components/Favoritos";
import HistorialCompras from "./components/HistorialCompras";
import Perfil from "./components/Perfil";
import Soporte  from "./components/Soporte";
import FAQ from "./components/FAQ";
import Publicar from "./components/Publicar";
import MiCatalogo from "./components/MiCatalogo";
import EditarProducto from "./components/EditarProducto";

function App() {

 return (

  <Router>

   <Routes>
<Route path="/login" element={<Login />} />
<Route path="/registro" element={<Register />} />
<Route path="/dashboard" element={<Dashboard />} />
<Route path="/dashboard-vendedor" element={<DashboardVendedor />} />
<Route path="/catalogo" element={<Catalogo />} />
<Route path="/producto/:id" element={<ProductoDetalle />} />
<Route path="/favoritos" element={<Favoritos />} />
<Route path="/historial-compras" element={<HistorialCompras />} />
<Route path="/perfil" element={<Perfil />} />
<Route path="/soporte" element={<Soporte />} />
<Route path="/faq" element={<FAQ />} />
<Route path="/publicar" element={<Publicar />} />
<Route path="/mi-catalogo" element={<MiCatalogo />} />
<Route path="/editar-producto/:id_producto" element={<EditarProducto />} />

   </Routes>

  </Router>

 );

}

export default App;
